"""roster greetings, follow-ups, cause shouts, calm + staff/event voices (249 clips). Written by the voice director (content), source AssetGen/audio/script/wave_*.txt -> voice_script.json; voice = char_id (VOIX_ARCHITECTURE.md principle 2). Never edit: new content goes to a new batch."""
ITEMS = [
    {'cat': 'greet', 'text': 'Bonsoir ! Colonel de cavalerie, en retraite. Repos !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_colonel_greet_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Hm ? Ah, bonsoir. On ne se présente plus, chez les civils ?', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_colonel_greet_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Garde-à-vous ! Ha, je plaisante. Bonsoir.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_colonel_greet_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Vous étiez à Verdun ? Non ? Dommage.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_colonel_greet_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Qui va là ? Ah, un invité. Bonsoir.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_colonel_greet_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Tenez-vous droit, on est en société.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_colonel_greet_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir, bonsoir. Le cognac est au fumoir, suivez-moi.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_colonel_greet_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Ah ! Enfin quelqu'un qui ne danse pas ce jazz de malheur.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_colonel_greet_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Belle tenue. Un peu civile, mais belle.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_colonel_greet_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Vous montez à cheval ? Ça se voit tout de suite.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_colonel_greet_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Rompez, rompez, je ne mords pas.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_colonel_greet_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Une poignée de main ferme, j'espère ?", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_colonel_greet_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Encore vous ? Rompez !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_again_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Vous avez un rapport à me faire ?', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_again_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Parlez, soldat, je vous écoute.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_again_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Vous me suivez comme une ordonnance, ma parole.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_colonel_again_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'shout', 'text': 'À couvert ! Ça tire !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_colonel_shout_gun_01', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Coup de feu ! Tout le monde à terre !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_colonel_shout_gun_02', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Feu ennemi ! Repliez-vous !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_colonel_shout_gun_03', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': "Incendie ! Formez une chaîne, nom d'un chien !", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_colonel_shout_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': 'Le feu ! Évacuez par la droite, au pas de course !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_colonel_shout_fire_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': 'Un obus ! Enfin, une explosion ! À terre !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_colonel_shout_explosion_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'explosion'},
    {'cat': 'shout', 'text': 'Ça a sauté ! Personne ne bouge, on compte les blessés !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_colonel_shout_explosion_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'explosion'},
    {'cat': 'shout', 'text': 'Panne de lumière ! Que personne ne bouge !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_colonel_shout_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'blackout'},
    {'cat': 'shout', 'text': "Qu'on m'apporte une lampe, et vite !", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_colonel_shout_blackout_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'blackout'},
    {'cat': 'shout', 'text': 'Par ici ! Suivez-moi, en ordre !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_colonel_shout_generic_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'shout', 'text': 'Pas de panique ! Enfin si, un peu, mais en ordre !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_colonel_shout_generic_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'shout', 'text': 'Retraite ! Retraite générale !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_colonel_shout_generic_03', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'calm', 'text': "Bon. Rapport des pertes, quelqu'un ?", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_colonel_calm_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "J'ai vu pire. Pas souvent, mais j'ai vu pire.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_colonel_calm_02', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Rassemblement, tout le monde. Ça va, ça va.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_colonel_calm_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Ma main ne tremble pas. C'est le froid.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_colonel_calm_04', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Un cognac. Double. C'est un ordre.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_colonel_calm_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Restez près de moi, j'ai l'habitude.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_colonel_calm_06', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Entrez de votre plein gré.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_comte_greet_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Ah, bonsoir. Quelle nuit délicieuse, n'est-ce pas ?", 'voice': 'char_comte', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_comte_greet_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Comte Vasilescu, pour vous servir. Bonsoir.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_comte_greet_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Vous avez une mine superbe. Très... sanguine.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_comte_greet_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. N'ayez pas peur, je ne mords que les jours de fête.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_comte_greet_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Ah, un visiteur nocturne. Bonsoir.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_comte_greet_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Vous venez de loin ? Moi, de très loin, et de très longtemps.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_comte_greet_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Les nuits d'orage sont mes préférées.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_comte_greet_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Enchanté. Sincèrement, profondément enchanté.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_comte_greet_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Approchez, que je vous voie mieux.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_comte_greet_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Vous sentez bon. Pas l'ail, j'espère ?", 'voice': 'char_comte', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_comte_greet_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Ah, bonsoir. Je vous attendais. Enfin, quelqu'un comme vous.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_comte_greet_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': "Vous revenez ? J'en suis flatté.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_again_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Encore vous ? La nuit est longue, nous avons le temps.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_again_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Vous tenez donc tant à ma compagnie ?', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_again_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': "Prudence. On finit toujours par s'attacher à moi.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_comte_again_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'shout', 'text': 'Un coup de feu ! Quelle vulgarité !', 'voice': 'char_comte', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_comte_shout_gun_01', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Des balles ? Heureusement, elles ne sont pas en argent !', 'voice': 'char_comte', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_comte_shout_gun_02', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Baissez-vous, mes amis, on tire !', 'voice': 'char_comte', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_comte_shout_gun_03', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Le feu ! Je déteste le feu !', 'voice': 'char_comte', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_comte_shout_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': 'Reculez, la flamme ne pardonne pas !', 'voice': 'char_comte', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_comte_shout_fire_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': 'Une explosion ! Qui ose troubler ma nuit ?', 'voice': 'char_comte', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_comte_shout_explosion_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'explosion'},
    {'cat': 'shout', 'text': 'Par tous mes ancêtres, quelle déflagration !', 'voice': 'char_comte', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_comte_shout_explosion_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'explosion'},
    {'cat': 'shout', 'text': "L'obscurité ! Enfin... je veux dire : quelle horreur !", 'voice': 'char_comte', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_comte_shout_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'blackout'},
    {'cat': 'shout', 'text': 'Restez calmes, je vois très bien dans le noir.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_comte_shout_blackout_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'blackout'},
    {'cat': 'shout', 'text': 'Fuyez, mortels ! Euh... fuyez, mes amis !', 'voice': 'char_comte', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_comte_shout_generic_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'shout', 'text': 'Par ici, suivez ma voix !', 'voice': 'char_comte', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_comte_shout_generic_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'shout', 'text': 'Que se passe-t-il ? Qui crie ainsi ?', 'voice': 'char_comte', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_comte_shout_generic_03', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'calm', 'text': 'Bien. La nuit reprend ses droits.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_comte_calm_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Le sang a coulé. Je n'y ai pas touché, je le jure.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_comte_calm_02', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Remettez-vous, il reste du bordeaux.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_comte_calm_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Ces gens crient beaucoup, pour des vivants.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_comte_calm_04', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Quel spectacle. Presque comme au bon vieux temps.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_comte_calm_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "N'allez pas dans les couloirs sans compagnie, cette nuit.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_comte_calm_06', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir ! Avec ces masques, je ne sais même plus à qui je souris.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_f_gown_greet_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Oh, bonsoir ! Vous tombez bien, je m'ennuyais.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_f_gown_greet_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Vous avez entendu la dernière ? Non ? Approchez.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_f_gown_greet_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Jolie silhouette. On la remarque de loin.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_f_gown_greet_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Ah, bonsoir. Je parie que vous avez un secret, vous.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_f_gown_greet_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir ! Ne me dites pas votre nom, je préfère deviner.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_f_gown_greet_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Vous m'offrez une coupe, ou je vous l'offre ?", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_f_gown_greet_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Oh, bonsoir. Vous ressemblez à mon deuxième fiancé. C'est un compliment.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_f_gown_greet_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Il paraît que vous savez danser. Prouvez-le.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_f_gown_greet_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Méfiez-vous, je répète tout ce qu'on me dit.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_f_gown_greet_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir ! Ce bal était d'un ennui avant votre arrivée.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_f_gown_greet_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Vous avez un très beau masque. Je le veux.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_f_gown_greet_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Encore vous ? On va finir par parler de nous.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_again_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': "Vous voulez un autre ragot, c'est ça ?", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_again_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Revenir si vite ? Vous êtes adorable.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_again_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Attention, mon fiancé est jaloux. Lequel ? Peu importe.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_f_gown_again_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'shout', 'text': 'Il a tiré ! Ma robe ! Pas sur ma robe !', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_f_gown_shout_gun_01', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': "Un coup de feu ! Quelqu'un, protégez-moi !", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_f_gown_shout_gun_02', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Il tire ! Mais il est complètement fou !', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_f_gown_shout_gun_03', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Au feu ! Mes cheveux vont brûler !', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_f_gown_shout_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': 'Laissez-moi passer, ça brûle, je suis trop jeune pour ça !', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_f_gown_shout_fire_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': "Une explosion ! Mon Dieu, mes boucles d'oreilles !", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_f_gown_shout_explosion_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'explosion'},
    {'cat': 'shout', 'text': 'Tout a sauté ! Où est la sortie ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_f_gown_shout_explosion_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'explosion'},
    {'cat': 'shout', 'text': 'Il fait noir ! Qui me touche la taille ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'startled', 'line_id': 'L_f_gown_shout_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'blackout'},
    {'cat': 'shout', 'text': 'Rallumez, je ne vois plus mes bijoux !', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'startled', 'line_id': 'L_f_gown_shout_blackout_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'blackout'},
    {'cat': 'shout', 'text': 'Écartez-vous, laissez passer une dame !', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_f_gown_shout_generic_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'shout', 'text': "Au secours, quelqu'un ! N'importe qui !", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_f_gown_shout_generic_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'shout', 'text': 'Victor ! Victor, où êtes-vous ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_f_gown_shout_generic_03', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'calm', 'text': "J'ai cassé un talon. La soirée est fichue.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'whisper', 'line_id': 'L_f_gown_calm_01', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Bon. Je suis toujours la plus belle ? Parfait.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'awkward', 'line_id': 'L_f_gown_calm_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Je sais qui a fait ça. Je vous le dirai plus tard.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'whisper', 'line_id': 'L_f_gown_calm_03', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Quelle émotion. J'ai besoin d'une coupe. Deux.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'awkward', 'line_id': 'L_f_gown_calm_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Mon rimmel a coulé ? Dites-moi la vérité.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'whisper', 'line_id': 'L_f_gown_calm_05', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Ce genre de chose n'arrive jamais à Deauville.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'awkward', 'line_id': 'L_f_gown_calm_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Victor, pour vous servir. Et pour vous plaire.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_m_tailcoat_greet_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Ah, bonsoir ! Vous jouez aux cartes, par hasard ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_m_tailcoat_greet_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Quelle élégance. Presque autant que moi.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_m_tailcoat_greet_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Vous auriez une petite pièce ? Non, je plaisante. Bonsoir.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_m_tailcoat_greet_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir ! Je ne vous connais pas, mais j'aimerais.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_m_tailcoat_greet_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Votre masque est superbe. Le mien aussi, d'ailleurs.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_m_tailcoat_greet_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. On m'a dit de me méfier des gens comme vous. J'adore ça.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_m_tailcoat_greet_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Ah, bonsoir. Vous ne venez pas réclamer une dette, au moins ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_m_tailcoat_greet_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. La nuit est jeune, et moi aussi. Enfin, presque.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_m_tailcoat_greet_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Un pari ? Je parie que vous allez sourire.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_m_tailcoat_greet_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Ma queue-de-pie vous plaît ? Elle n'est pas encore payée.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_m_tailcoat_greet_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Vous dansez ? Moi, divinement.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_m_tailcoat_greet_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Vous revoilà ? Je savais que je vous plairais.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_again_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': "Encore ? Je commence à m'attacher.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_again_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': "Si c'est pour l'argent que je vous dois, je ne vous connais pas.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_again_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Vous revenez me porter chance ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_m_tailcoat_again_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'shout', 'text': "Ils tirent ! Ma queue-de-pie, je l'ai louée !", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_m_tailcoat_shout_gun_01', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': "Un coup de feu ! Je ne dois pas tant d'argent que ça !", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_m_tailcoat_shout_gun_02', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'À terre ! On tire dans la salle !', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_m_tailcoat_shout_gun_03', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Le feu ! Sauvez le champagne !', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_m_tailcoat_shout_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': 'Ça brûle ! Ma queue-de-pie va prendre feu !', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_m_tailcoat_shout_fire_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': "Une explosion ! Ce n'est pas moi, je le jure !", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_m_tailcoat_shout_explosion_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'explosion'},
    {'cat': 'shout', 'text': "Ça a sauté ! Les dames et les élégants d'abord !", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_m_tailcoat_shout_explosion_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'explosion'},
    {'cat': 'shout', 'text': 'Plus de lumière ! Qui a mis la main dans ma poche ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_m_tailcoat_shout_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'blackout'},
    {'cat': 'shout', 'text': 'Il fait noir ! Parfait pour filer sans payer.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_m_tailcoat_shout_blackout_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'blackout'},
    {'cat': 'shout', 'text': "Sauve qui peut ! Moi d'abord !", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_m_tailcoat_shout_generic_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'shout', 'text': 'Laissez passer, je suis attendu ailleurs !', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_m_tailcoat_shout_generic_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'shout', 'text': 'Quelle pagaille ! Par ici, vite !', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_m_tailcoat_shout_generic_03', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'calm', 'text': "Bon. J'ai toujours ma montre ? Ah non, je l'avais déjà perdue.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_m_tailcoat_calm_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Si quelqu'un demande, j'étais au bar. Avec vous.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_m_tailcoat_calm_02', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Rien de grave. Ma coiffure a survécu.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_m_tailcoat_calm_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Ils vont fouiller tout le monde. J'ai des cartes dans la manche.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_m_tailcoat_calm_04', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Une émotion pareille, ça mérite une coupe.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_m_tailcoat_calm_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Je crois que j'ai semé mes créanciers dans la bousculade.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_m_tailcoat_calm_06', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Je vous observais.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_minuit_greet_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Minuit. Enfin, c'est ainsi qu'on m'appelle.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_minuit_greet_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Ne vous retournez pas.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_minuit_greet_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Personne n'est celui qu'il prétend, ce soir. Vous non plus.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_minuit_greet_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Hm. Bonsoir.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_minuit_greet_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Restez dans la lumière, c'est plus sûr.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_minuit_greet_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Vous avez vu quelque chose d'étrange ?", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_minuit_greet_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Parlez bas, les murs écoutent.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_minuit_greet_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'La nuit vous va bien. Bonsoir.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_minuit_greet_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Je sais ce que vous cachez. Je plaisante. Peut-être.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_minuit_greet_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Vous marchez trop vite pour un simple invité.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_minuit_greet_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Gardez votre masque. Il vous protège.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'warm', 'line_id': 'L_minuit_greet_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Encore vous. Intéressant.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_again_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Vous cherchez quelque chose ?', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_again_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': "Je n'ai rien de plus à dire. Pour l'instant.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_again_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Votre insistance est notée.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_again_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'shout', 'text': 'Coup de feu ! Tout le monde à couvert !', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_minuit_shout_gun_01', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Le tireur est là-bas ! Baissez-vous !', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_minuit_shout_gun_02', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Une arme ! Éloignez-vous de lui !', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_minuit_shout_gun_03', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': "Le feu ! Sortez par l'autre côté !", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_minuit_shout_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': 'Fumée ! Restez bas et avancez !', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_minuit_shout_fire_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': 'Explosion ! Restez à terre !', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_minuit_shout_explosion_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'explosion'},
    {'cat': 'shout', 'text': "Une bombe ! Ce n'était pas un accident !", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_minuit_shout_explosion_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'explosion'},
    {'cat': 'shout', 'text': 'Panne ! Ne bougez pas, je vois dans le noir.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_minuit_shout_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'blackout'},
    {'cat': 'shout', 'text': "Quelqu'un a coupé le courant. Exprès.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_minuit_shout_blackout_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'blackout'},
    {'cat': 'shout', 'text': 'Par ici ! Suivez-moi !', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_minuit_shout_generic_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'shout', 'text': 'Restez calmes et dégagez la salle !', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_minuit_shout_generic_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'shout', 'text': 'Écartez-vous, laissez-moi passer !', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_minuit_shout_generic_03', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'calm', 'text': "Ce n'était pas un accident.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_minuit_calm_01', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Le coupable est encore parmi nous.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_minuit_calm_02', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Respirez. C'est terminé. Pour ce soir.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_minuit_calm_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Regardez qui sourit, maintenant.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_minuit_calm_04', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Revenez dans la lumière. Tous.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_minuit_calm_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Je l'ai vu. Je le retrouverai.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'whisper', 'line_id': 'L_minuit_calm_06', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir, mon chou ! T'as une bonne tête, toi.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_odette_greet_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Salut ! Euh, pardon : bonsoir. On est chez les rupins.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_odette_greet_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir ! Tu viens m'écouter chanter, tout à l'heure ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_odette_greet_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Tiens, bonsoir ! On s'est pas croisés au cabaret, nous deux ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_odette_greet_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. Fais pas cette tête, c'est une fête !", 'voice': 'char_odette', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_odette_greet_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Oh, bonsoir ! Joli masque. Le mien a plus de plumes.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_odette_greet_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir, bonsoir ! T'aurais pas une cigarette ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_odette_greet_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir ! Méfie-toi, je mords pas, mais je chante.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_odette_greet_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir. T'as l'air de chercher quelqu'un. Ou le bar.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_odette_greet_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir, mon petit. Odette, du cabaret. Tu connais ?', 'voice': 'char_odette', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_odette_greet_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Bonsoir ! Enfin quelqu'un qui sourit, dans ce mausolée.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_odette_greet_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': "Ah, bonsoir ! Toi, je sens qu'on va bien s'entendre.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_odette_greet_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Encore toi ? Tu veux un autographe ?', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_again_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': "Qu'est-ce qu'il y a, mon chou ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_again_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Toi, tu me suis. Ça me flatte.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_again_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Si tu reviens encore, je te fais chanter avec moi.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_again_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'shout', 'text': 'Ils tirent ! Planquez-vous !', 'voice': 'char_odette', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_odette_shout_gun_01', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': "Un coup de feu ! C'est pas du cinéma, là !", 'voice': 'char_odette', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_odette_shout_gun_02', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Baissez-vous, il est fou, celui-là !', 'voice': 'char_odette', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_odette_shout_gun_03', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
    {'cat': 'shout', 'text': 'Au feu ! Ça crame de partout !', 'voice': 'char_odette', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_odette_shout_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': 'Le feu ! Mes plumes vont flamber !', 'voice': 'char_odette', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_odette_shout_fire_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
    {'cat': 'shout', 'text': "Ça a pété ! Qu'est-ce que c'était ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_odette_shout_explosion_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'explosion'},
    {'cat': 'shout', 'text': "Une bombe ! Mais où est-ce qu'on est tombés ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_odette_shout_explosion_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'explosion'},
    {'cat': 'shout', 'text': 'Hé ! Qui a coupé la lumière ?', 'voice': 'char_odette', 'gender': 'f', 'reg': 'startled', 'line_id': 'L_odette_shout_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'blackout'},
    {'cat': 'shout', 'text': 'Bas les pattes, toi, dans le noir !', 'voice': 'char_odette', 'gender': 'f', 'reg': 'startled', 'line_id': 'L_odette_shout_blackout_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'blackout'},
    {'cat': 'shout', 'text': "Courez ! Courez, nom d'une pipe !", 'voice': 'char_odette', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_odette_shout_generic_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'shout', 'text': 'Poussez pas, on va tous y passer !', 'voice': 'char_odette', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_odette_shout_generic_02', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'shout', 'text': 'Maman ! Je veux retourner à Pigalle !', 'voice': 'char_odette', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_odette_shout_generic_03', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'generic'},
    {'cat': 'calm', 'text': "J'ai le cœur qui bat comme une grosse caisse.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'whisper', 'line_id': 'L_odette_calm_01', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Bon, ben... ça, c'est fait.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'awkward', 'line_id': 'L_odette_calm_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "Je l'avais dit qu'il fallait pas venir.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'whisper', 'line_id': 'L_odette_calm_03', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Allez, on se remet. Un petit verre et ça repart.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'awkward', 'line_id': 'L_odette_calm_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': "T'as vu sa tête ? J'en rêverai cette nuit.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'whisper', 'line_id': 'L_odette_calm_05', 'whispered': True, 'nonverbal': False, 'gun': False},
    {'cat': 'calm', 'text': 'Même à Pigalle, on voit pas ça un samedi.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'awkward', 'line_id': 'L_odette_calm_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'barman', 'text': 'Et voilà pour vous. Avec les compliments de la maison.', 'voice': 'char_barman', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barman_barman_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'barman', 'text': 'Bon choix. Je ne dirai rien à personne.', 'voice': 'char_barman', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barman_barman_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'barman', 'text': "Tenez. Et ce n'est pas moi qui vous l'ai vendu.", 'voice': 'char_barman', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barman_barman_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'barman', 'text': 'Voilà. Discrétion assurée.', 'voice': 'char_barman', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barman_barman_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'barman', 'text': 'Excellent choix, vraiment.', 'voice': 'char_barman', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barman_barman_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'barman', 'text': "C'est noté. Au plaisir.", 'voice': 'char_barman', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barman_barman_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'barman', 'text': 'Avec ça, vous allez faire des envieux.', 'voice': 'char_barman', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barman_barman_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'barman', 'text': "Prenez-en soin, c'est le dernier. Enfin, presque.", 'voice': 'char_barman', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barman_barman_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'barman', 'text': "Merci bien. Le pourboire n'est pas obligatoire, mais conseillé.", 'voice': 'char_barman', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barman_barman_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'barman', 'text': 'Voilà votre affaire. Bonne soirée.', 'voice': 'char_barman', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barman_barman_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'barman', 'text': "Je vous l'emballe ? Non, je plaisante.", 'voice': 'char_barman', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barman_barman_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'barman', 'text': "Pour vous, j'ai fait un prix. Enfin, un petit.", 'voice': 'char_barman', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barman_barman_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'barman', 'text': "Faites-en bon usage. Ou mauvais, ce n'est pas mon affaire.", 'voice': 'char_barman', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barman_barman_13', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'barman', 'text': 'Ça marche ! Revenez quand vous voulez.', 'voice': 'char_barman', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barman_barman_14', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'barman', 'text': "Vendu. Et n'oubliez pas : vous ne m'avez jamais vu.", 'voice': 'char_barman', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barman_barman_15', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze', 'text': 'Vous allez tous sauter avec moi !', 'voice': 'char_kamikaze', 'gender': 'm', 'reg': 'manic', 'line_id': 'L_kamikaze_self_kamikaze_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze', 'text': "Personne ne m'arrêtera, personne !", 'voice': 'char_kamikaze', 'gender': 'm', 'reg': 'manic', 'line_id': 'L_kamikaze_self_kamikaze_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze', 'text': 'Le grand boum approche, mes amis !', 'voice': 'char_kamikaze', 'gender': 'm', 'reg': 'manic', 'line_id': 'L_kamikaze_self_kamikaze_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze', 'text': 'Fuyez tant que vous voulez, je suis plus rapide !', 'voice': 'char_kamikaze', 'gender': 'm', 'reg': 'manic', 'line_id': 'L_kamikaze_self_kamikaze_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze', 'text': "J'ai assez de dynamite pour tout le manoir !", 'voice': 'char_kamikaze', 'gender': 'm', 'reg': 'manic', 'line_id': 'L_kamikaze_self_kamikaze_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze', 'text': "Ashcombe, c'est ta dernière soirée !", 'voice': 'char_kamikaze', 'gender': 'm', 'reg': 'manic', 'line_id': 'L_kamikaze_self_kamikaze_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze', 'text': 'Tic, tac, tic, tac ! Ha ha ha !', 'voice': 'char_kamikaze', 'gender': 'm', 'reg': 'manic', 'line_id': 'L_kamikaze_self_kamikaze_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze', 'text': 'Adieu, la haute société !', 'voice': 'char_kamikaze', 'gender': 'm', 'reg': 'manic', 'line_id': 'L_kamikaze_self_kamikaze_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_voice', 'text': 'Intrus détecté.', 'voice': 'char_robot', 'gender': 'm', 'reg': 'flat', 'line_id': 'L_robot_self_robot_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_voice', 'text': 'Analyse du visage.', 'voice': 'char_robot', 'gender': 'm', 'reg': 'flat', 'line_id': 'L_robot_self_robot_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_voice', 'text': "Vous n'êtes pas sur la liste des invités.", 'voice': 'char_robot', 'gender': 'm', 'reg': 'flat', 'line_id': 'L_robot_self_robot_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_voice', 'text': 'Ne bougez plus.', 'voice': 'char_robot', 'gender': 'm', 'reg': 'flat', 'line_id': 'L_robot_self_robot_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_voice', 'text': 'Élimination autorisée.', 'voice': 'char_robot', 'gender': 'm', 'reg': 'flat', 'line_id': 'L_robot_self_robot_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_voice', 'text': 'Cible verrouillée.', 'voice': 'char_robot', 'gender': 'm', 'reg': 'flat', 'line_id': 'L_robot_self_robot_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_voice', 'text': 'Protocole de sécurité activé.', 'voice': 'char_robot', 'gender': 'm', 'reg': 'flat', 'line_id': 'L_robot_self_robot_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_voice', 'text': 'Veuillez rester immobile.', 'voice': 'char_robot', 'gender': 'm', 'reg': 'flat', 'line_id': 'L_robot_self_robot_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_voice', 'text': 'Signature thermique repérée.', 'voice': 'char_robot', 'gender': 'm', 'reg': 'flat', 'line_id': 'L_robot_self_robot_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_voice', 'text': 'Mission : nettoyer la fête.', 'voice': 'char_robot', 'gender': 'm', 'reg': 'flat', 'line_id': 'L_robot_self_robot_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_bandit', 'text': 'Les bijoux dans le sac, et plus vite que ça !', 'voice': 'char_bandit', 'gender': 'm', 'reg': 'threat', 'line_id': 'L_bandit_self_bandit_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_bandit', 'text': 'Toi, le gros, vide tes poches !', 'voice': 'char_bandit', 'gender': 'm', 'reg': 'threat', 'line_id': 'L_bandit_self_bandit_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_bandit', 'text': 'Personne ne joue au héros, compris ?', 'voice': 'char_bandit', 'gender': 'm', 'reg': 'threat', 'line_id': 'L_bandit_self_bandit_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_bandit', 'text': 'On est venus pour le coffre, pas pour danser !', 'voice': 'char_bandit', 'gender': 'm', 'reg': 'threat', 'line_id': 'L_bandit_self_bandit_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_bandit', 'text': 'Un geste et je tire !', 'voice': 'char_bandit', 'gender': 'm', 'reg': 'threat', 'line_id': 'L_bandit_self_bandit_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_bandit', 'text': 'Allez, allez, les colliers aussi !', 'voice': 'char_bandit', 'gender': 'm', 'reg': 'threat', 'line_id': 'L_bandit_self_bandit_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_bandit', 'text': 'Hé, la comtesse, tes perles, vite !', 'voice': 'char_bandit2', 'gender': 'm', 'reg': 'threat', 'line_id': 'L_bandit2_self_bandit_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_bandit', 'text': 'Regardez-les, ils tremblent comme des feuilles !', 'voice': 'char_bandit2', 'gender': 'm', 'reg': 'threat', 'line_id': 'L_bandit2_self_bandit_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_bandit', 'text': "Bouge pas, toi, ou je t'arrange le portrait !", 'voice': 'char_bandit2', 'gender': 'm', 'reg': 'threat', 'line_id': 'L_bandit2_self_bandit_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_bandit', 'text': 'Plus vite que ça, les rupins !', 'voice': 'char_bandit2', 'gender': 'm', 'reg': 'threat', 'line_id': 'L_bandit2_self_bandit_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_bandit', 'text': 'On prend tout, même les petits fours !', 'voice': 'char_bandit2', 'gender': 'm', 'reg': 'threat', 'line_id': 'L_bandit2_self_bandit_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_bandit', 'text': 'Le premier qui piaille, il goûte à mon pétard !', 'voice': 'char_bandit2', 'gender': 'm', 'reg': 'threat', 'line_id': 'L_bandit2_self_bandit_06', 'whispered': False, 'nonverbal': False, 'gun': False},
]
